/** Offline showcase: authored carton generated by the actual img2threejs factory. */
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { createOpenFoldingCartonModel } from './factory.ts';
import { certifyFoldSweep } from './hinge_sweep_collision.mjs';

const ids = ['back-flap', 'front-flap', 'left-flap', 'right-flap'];
const labels = {
  'back-flap': 'Back flap',
  'front-flap': 'Front flap',
  'left-flap': 'Left flap',
  'right-flap': 'Right flap',
};
const referencePose = { 'back-flap': 22, 'front-flap': -65,
  'left-flap': -24, 'right-flap': 32 };
const values = Object.fromEntries(ids.map(id => [id, 0]));
const root = createOpenFoldingCartonModel();
const runtime = root.userData.sculptRuntime;
const stage = document.getElementById('stage');
if (!runtime?.hinges || ids.some(id => !runtime.hinges[id] || !runtime.meshes[id])) {
  throw new Error('hinge lab requires the generated four-panel runtime');
}
document.getElementById('panel-count').textContent = String(ids.length);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0f1724);
scene.add(root);
scene.add(new THREE.HemisphereLight(0xfaf5f1, 0x344059, 2.5));
const sun = new THREE.DirectionalLight(0xffffff, 2.6);
sun.position.set(4, 7, 5);
scene.add(sun);
const lightBack = new THREE.DirectionalLight(0xb7c8e8, 0.8);
lightBack.position.set(-3, 3, -6);
scene.add(lightBack);
const renderer = new THREE.WebGLRenderer({
  canvas: stage, antialias: true, alpha: false,
  preserveDrawingBuffer: true,
});
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
const camera = new THREE.PerspectiveCamera(44, 1, 0.01, 120);
camera.position.set(3.65, 3.25, 4.8);
camera.lookAt(0, 0, 0);
const controls = new OrbitControls(camera, stage);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.minDistance = 2.1;
controls.maxDistance = 12;
controls.target.set(0, 0, 0);
const guide = new THREE.GridHelper(6, 12, 0x506479, 0x243348);
guide.position.y = -0.12;
scene.add(guide);
const cardboard = new THREE.MeshStandardMaterial({
  color: 0xb98a69, roughness: 0.91, metalness: 0,
  side: THREE.DoubleSide,
});
const edgeMaterial = new THREE.LineBasicMaterial({
  color: 0x4f392d, transparent: true, opacity: 0.65,
});
for (const mesh of Object.values(runtime.meshes)) {
  const old = mesh.material;
  mesh.material = cardboard;
  if (Array.isArray(old)) old.forEach(material => material.dispose());
  else if (old && old !== cardboard) old.dispose();
  const outline = new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry), edgeMaterial);
  mesh.add(outline);
}
const obstacle = new THREE.Mesh(
  new THREE.BoxGeometry(0.13, 0.13, 0.13),
  new THREE.MeshStandardMaterial({color:0xe85e55, roughness:0.78}),
);
obstacle.visible = false;
scene.add(obstacle);
const collider = document.getElementById('collision-part');
const checkbox = document.getElementById('obstacle-enabled');
const statusBox = document.getElementById('status');
const statusTitle = document.getElementById('status-title');
const statusDetail = document.getElementById('status-detail');
const sliders = document.getElementById('sliders');
let lastEvaluation = null;
let previousWidth = 0, previousHeight = 0;

function setStatus(state, title, detail) {
  statusBox.dataset.state = state;
  statusTitle.textContent = title;
  statusDetail.textContent = detail;
}
function invalidateStatus() {
  lastEvaluation = null;
  setStatus('inactive', 'Not evaluated', 'Select a panel and evaluate its path.');
}
function fitCanvas() {
  const bounds = stage.getBoundingClientRect();
  const width = Math.max(1, Math.floor(bounds.width));
  const height = Math.max(1, Math.floor(bounds.height));
  if (width !== previousWidth || height !== previousHeight) {
    previousWidth = width; previousHeight = height;
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  }
}
function applyPose() {
  for (const id of ids) {
    runtime.hinges[id].rotation.y = THREE.MathUtils.degToRad(values[id]);
    const output = document.getElementById('value-' + id);
    const slider = document.getElementById('slider-' + id);
    if (output) output.value = values[id] + '°';
    if (slider) slider.value = String(values[id]);
  }
  root.updateMatrixWorld(true);
  document.getElementById('joint-angle').textContent =
    labels[collider.value] + ': ' + values[collider.value] + '°';
}
function setFold(id, angle) {
  if (!ids.includes(id) || !Number.isFinite(angle) || angle < -180 || angle > 180) {
    throw new RangeError('unknown fold or out-of-range angle');
  }
  values[id] = Math.round(angle * 1000) / 1000;
  applyPose();
  invalidateStatus();
  return getStatus();
}
function applyAll(pose) {
  for (const id of ids) values[id] = pose[id] ?? 0;
  applyPose();
  invalidateStatus();
}
function placeObstacle() {
  if (!checkbox.checked) {
    obstacle.visible = false;
    invalidateStatus();
    return;
  }
  const id = collider.value;
  const hinge = runtime.hinges[id];
  const saved = hinge.rotation.y;
  try {
    hinge.rotation.y = Math.PI / 2;
    root.updateMatrixWorld(true);
    obstacle.position.copy(runtime.meshes[id].getWorldPosition(new THREE.Vector3()));
  } finally {
    hinge.rotation.y = saved;
    root.updateMatrixWorld(true);
  }
  obstacle.visible = true;
  invalidateStatus();
}
function evaluate() {
  if (!checkbox.checked) {
    setStatus('inactive', 'Not evaluated', 'Enable the obstacle first.');
    return null;
  }
  const id = collider.value;
  const result = certifyFoldSweep(runtime.hinges[id], runtime.meshes[id],
    obstacle, 0, values[id], {maxDepth:16, maxChecks:4096});
  lastEvaluation = {component:id, targetDegrees:values[id], ...result};
  const heading = result.status === 'collision' ? 'Collision detected'
    : result.status === 'certified-clear' ? 'Certified clear*' : 'Unresolved';
  const detail = result.status === 'collision'
    ? 'Intersection at ' + result.collision.degrees.toFixed(3) + '°; ' +
      'penetration ' + result.collision.overlap.toFixed(4) + ' units'
    : result.status === 'certified-clear'
      ? result.evaluatedAngles + ' checks · ' + result.certifiedIntervals +
        ' certified intervals · rigid static-box assumptions only'
      : 'Unable to prove the whole sweep clear. ' +
        result.unresolvedIntervals.length + ' intervals unresolved.';
  setStatus(result.status, heading, detail);
  return lastEvaluation;
}
function getStatus() {
  return {
    angles: {...values},
    selected: collider.value,
    obstacleEnabled:checkbox.checked,
    obstaclePosition:obstacle.position.toArray(),
    obstacleVisible:obstacle.visible,
    lastEvaluation,
    drawCalls:renderer.info.render.calls,
    triangles:renderer.info.render.triangles,
  };
}
function render() {
  fitCanvas();
  controls.update();
  renderer.render(scene, camera);
  document.getElementById('triangle-count').textContent =
    renderer.info.render.triangles.toLocaleString();
}
let raf;
function loop() {
  render();
  raf = window.requestAnimationFrame(loop);
}
for (const id of ids) {
  const label = document.createElement('label');
  label.className = 'slider-field';
  const head = document.createElement('span');
  head.className = 'field-head';
  const name = document.createElement('span');
  name.textContent = labels[id];
  const output = document.createElement('output');
  output.id = 'value-' + id;
  output.htmlFor = 'slider-' + id;
  head.append(name, output);
  const slider = document.createElement('input');
  slider.type = 'range';
  slider.min = '-180'; slider.max = '180'; slider.step = '1';
  slider.value = '0';
  slider.id = 'slider-' + id;
  slider.setAttribute('aria-label', labels[id] + ' angle');
  slider.addEventListener('input', () => setFold(id, Number(slider.value)));
  label.append(head, slider);
  sliders.append(label);
}
document.getElementById('rest').addEventListener('click', () => applyAll({}));
document.getElementById('pose').addEventListener('click', () => applyAll(referencePose));
document.getElementById('check').addEventListener('click', evaluate);
checkbox.addEventListener('change', placeObstacle);
collider.addEventListener('change', placeObstacle);
document.getElementById('export').addEventListener('click', () => {
  const json = JSON.stringify({
    format:'img2threejs.hinge-lab-pose.v1', anglesDegrees:{...values},
    source:'study/hinge-real-photo-ab-20261019', collision:lastEvaluation
  }, null, 2) + '\n';
  const href = URL.createObjectURL(new Blob([json], {type:'application/json'}));
  const a = document.createElement('a');
  a.href = href; a.download = 'hinge-lab-pose.json';
  document.body.append(a); a.click(); a.remove();
  URL.revokeObjectURL(href);
});
const importFile = document.getElementById('import-file');
document.getElementById('import').addEventListener('click', () => importFile.click());
importFile.addEventListener('change', async () => {
  const file = importFile.files?.[0];
  if (!file) return;
  try {
    if (file.size < 2 || file.size > 64 * 1024) {
      throw new RangeError('Pose file size must be between 2 bytes and 64 KiB');
    }
    const parsed = JSON.parse(await file.text());
    if (parsed?.format !== 'img2threejs.hinge-lab-pose.v1' ||
        !parsed.anglesDegrees || typeof parsed.anglesDegrees !== 'object') {
      throw new Error('Unsupported pose format');
    }
    const angles = Object.fromEntries(ids.map(id => {
      const angle = parsed.anglesDegrees[id];
      if (typeof angle !== 'number' || !Number.isFinite(angle) ||
          angle < -180 || angle > 180) {
        throw new Error('Missing or invalid angle for ' + id);
      }
      return [id, angle];
    }));
    applyAll(angles);
    setStatus('inactive', 'Pose imported', file.name + ': four fold angles loaded locally.');
  } catch (error) {
    setStatus('unresolved', 'Import rejected', String(error.message || error));
  } finally {
    importFile.value = '';
  }
});
window.addEventListener('resize', render);
applyAll({});
render();
raf = window.requestAnimationFrame(loop);
window.__hingeLab = {
  getStatus, setFold, evaluate, setObstacle(enabled, id) {
    if (id !== undefined) {
      if (!ids.includes(id)) throw new RangeError('unknown panel');
      collider.value = id;
    }
    checkbox.checked = Boolean(enabled);
    placeObstacle();
  },
  setPreset(kind) {
    if (kind === 'photo') applyAll(referencePose);
    else if (kind === 'flat') applyAll({});
    else throw new RangeError('unknown pose');
  },
  screenshot() {
    render();
    return stage.toDataURL('image/png');
  },
  dispose() {
    if (raf) cancelAnimationFrame(raf);
    controls.dispose();
    renderer.dispose();
  },
};
window.__hingeLabReady = true;
